import{_ as c,C as t,o as l,c as d,a5 as s,E as r,j as e,a as i,b as A,w as E,a6 as u}from"./chunks/framework.D_J2JZBr.js";const k=JSON.parse('{"title":"数字 VLSI 与专用芯片","description":"从 RTL、FPGA 到芯片实现，认识上科大的数字电路与视觉专用芯片方向。","frontmatter":{"title":"数字 VLSI 与专用芯片","description":"从 RTL、FPGA 到芯片实现，认识上科大的数字电路与视觉专用芯片方向。"},"headers":[],"relativePath":"explore-ic/research-directions/digital-vlsi.md","filePath":"explore-ic/research-directions/digital-vlsi.md","lastUpdated":1795531638000}'),p={name:"explore-ic/research-directions/digital-vlsi.md"};function B(g,a,f,b,m,S){const n=t("FacultyList"),h=t("CourseTable"),o=t("Mermaid");return l(),d("div",null,[a[1]||(a[1]=s('<h1 id="数字-vlsi-与专用芯片" tabindex="-1">数字 VLSI 与专用芯片 <a class="header-anchor" href="#数字-vlsi-与专用芯片" aria-label="Permalink to &quot;数字 VLSI 与专用芯片&quot;">​</a></h1><h2 id="这个方向在做什么" tabindex="-1">这个方向在做什么 <a class="header-anchor" href="#这个方向在做什么" aria-label="Permalink to &quot;这个方向在做什么&quot;">​</a></h2><p>数字超大规模集成电路（Very-Large-Scale Integration，VLSI）研究如何用大量数字逻辑完成计算、控制和数据传输。专用集成电路（Application-Specific Integrated Circuit，ASIC）针对特定任务组织计算与存储；现场可编程门阵列（FPGA）提供可重配置的实现平台。两者都需要把算法映射到并行硬件，但器件资源、时序和成本约束不同。</p><p>核心研究问题包括：</p><ul><li>算法应怎样流水化、并行化，才能满足真实数据依赖与带宽约束？</li><li>如何在功耗、性能、面积（PPA）之间做可解释的权衡？</li><li>片上缓存、数据复用与片外访问怎样共同决定能耗？</li><li>如何用验证、可测性设计和时序分析保证实现正确？</li><li>综合、布局布线与工艺约束会怎样反过来改变架构选择？</li></ul><h2 id="上科大谁在做" tabindex="-1">上科大谁在做 <a class="header-anchor" href="#上科大谁在做" aria-label="Permalink to &quot;上科大谁在做&quot;">​</a></h2><p>上科大数字设计的公开研究既有应用定制，也有计算方法与平台。娄鑫的 VLSI 信号处理实验室（VSPLab）研究面向图像、图形和视觉的数字集成电路与系统，站内师资数据明确列出智能视觉、三维重建与渲染芯片。它是从视觉算法走向计算结构、存储组织与芯片实现的具体入口，详见 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/research-groups/vsplab">VSPLab 专页</a>，不要把软件渲染加速与专用芯片成果混为一谈。</p><p>哈亚军关注 FPGA 结构、设计工具及应用、超低功耗数字电路与系统，以及智能车和嵌入式系统。刘思廷关注先进计算电路与系统，包括动态随机计算、低比特计算和边缘 AI；任轩乐则连接隐私计算芯片、硬件安全与设计自动化。选择课题时，应进一步核对团队当前公开论文所采用的平台和评价方法。</p>',8)),r(n,{dir:"digital"}),a[2]||(a[2]=e("h2",{id:"相关上科大课程",tabindex:"-1"},[i("相关上科大课程 "),e("a",{class:"header-anchor",href:"#相关上科大课程","aria-label":'Permalink to "相关上科大课程"'},"​")],-1)),a[3]||(a[3]=e("p",null,"可沿数字电路、数字集成电路、FPGA 和 VLSI 流程逐步建立实现能力，工程课程与进阶选修的实际内容以当学期大纲为准。",-1)),r(h,{codes:"EE115B,EE113,EE113L,EE116,EE213,EE291F,EE2210,EE216"}),a[4]||(a[4]=e("p",null,[e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee113"},"EE113"),i(" 适合连接逻辑与电路实现，"),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee291f"},"EE291F"),i(" 则是理解数字设计流程的课程入口。")],-1)),a[5]||(a[5]=e("h2",{id:"知识前置",tabindex:"-1"},[i("知识前置 "),e("a",{class:"header-anchor",href:"#知识前置","aria-label":'Permalink to "知识前置"'},"​")],-1)),a[6]||(a[6]=e("p",null,"这是建议的知识依赖，不是教务先修表；编程、基本电路和离散数学可以交叉学习。",-1)),(l(),A(u,null,{default:E(()=>[r(o,{id:"mermaid-67",class:"mermaid",graph:"graph%20TD%0A%20%20A%5B%22CS100%20%E8%AE%A1%E7%AE%97%E6%9C%BA%E7%BC%96%E7%A8%8B%22%5D%20--%3E%20B%5B%22SI100B%20%E4%BF%A1%E6%81%AF%E7%A7%91%E5%AD%A6%E6%8A%80%E6%9C%AF%E5%AF%BC%E8%AE%BA%22%5D%0A%20%20C%5B%22EE111%20%E7%94%B5%E8%B7%AF%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20D%5B%22EE115B%20%E6%95%B0%E5%AD%97%E7%94%B5%E8%B7%AF%22%5D%0A%20%20B%20--%3E%20D%0A%20%20D%20--%3E%20E%5B%22EE113%20%E6%95%B0%E5%AD%97%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AFI%22%5D%0A%20%20D%20--%3E%20F%5B%22EE116%20%E5%9F%BA%E4%BA%8EFPGA%E7%9A%84%E7%A1%AC%E4%BB%B6%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20E%20--%3E%20G%5B%22EE291F%20%E6%95%B0%E5%AD%97VLSI%E8%AE%BE%E8%AE%A1%E6%B5%81%E7%A8%8B%22%5D%0A%20%20E%20--%3E%20H%5B%22EE2210%20%E6%95%B0%E5%AD%97%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AF%E5%8F%AF%E6%B5%8B%E6%80%A7%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20F%20--%3E%20I%5B%22EE216%20%E5%8F%AF%E9%87%8D%E6%9E%84%E8%AE%A1%E7%AE%97%22%5D%0A%20%20G%20--%3E%20J%5B%22%E6%95%B0%E5%AD%97%20VLSI%20%E4%B8%8E%E4%B8%93%E7%94%A8%E8%8A%AF%E7%89%87%22%5D%0A%20%20H%20--%3E%20J%0A%20%20I%20--%3E%20J%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="领域地图" tabindex="-1">领域地图 <a class="header-anchor" href="#领域地图" aria-label="Permalink to &quot;领域地图&quot;">​</a></h2><ul><li><strong>研究机构</strong>：Berkeley BWRC、MIT、清华、复旦等机构的数字电路与专用计算研究，可帮助区分电路创新、架构创新和系统应用创新。</li><li><strong>产业参照</strong>：NVIDIA、AMD、华为海思的计算芯片，AMD 和 Altera 的 FPGA，以及台积电的制造平台，分别位于不同环节；不构成本校合作名单。</li><li><strong>会议与期刊</strong>：ISSCC、VLSI Symposium、CICC、JSSC 偏重电路与芯片证据；FPGA、FPL 面向可重构系统；TCAS 与 TVLSI 也有相关研究。</li></ul><p>关注“用什么证据支持什么结论”：RTL 仿真、FPGA 原型、综合报告、布局布线结果与流片实测不是同一级别。比较 PPA 必须说明工艺、频率、精度、数据集和外部存储条件。</p><h2 id="入门资源" tabindex="-1">入门资源 <a class="header-anchor" href="#入门资源" aria-label="Permalink to &quot;入门资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/resources">数字自学</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/">数字学习地图</a>：安排 HDL、验证与实现路径。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/knowledge-map">设计流程</a> 与 <a href="/shanghaitech-ic-wiki-dev.github.io/tools/open-source/">开源 EDA</a>：理解工具链各阶段的输入输出。</li><li><a href="https://hdlbits.01xz.net/" target="_blank" rel="noreferrer">HDLBits</a>：练习组合逻辑、时序逻辑和 Verilog。</li><li><a href="https://ysyx.oscc.cc/" target="_blank" rel="noreferrer">一生一芯</a>：系统化处理器与工程实践入口。</li></ul><p>建议从一个有明确测试向量的小模块开始，先完成自检验证，再观察综合和时序结果。不要把“仿真看起来对”当成设计已经收敛。</p><h2 id="社区经验征集" tabindex="-1">社区经验征集 <a class="header-anchor" href="#社区经验征集" aria-label="Permalink to &quot;社区经验征集&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎数字芯片课题组同学通过 <a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a> 补充“组里在做什么”、公开项目的实现边界、验证习惯与进组准备建议；请勿披露未公开 RTL、工艺库或流片数据。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/louxin/main.htm" target="_blank" rel="noreferrer">娄鑫学院主页</a>、<a href="https://vsplab.cn/" target="_blank" rel="noreferrer">VSPLab</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/hayj/main.htm" target="_blank" rel="noreferrer">哈亚军学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/liust/main.htm" target="_blank" rel="noreferrer">刘思廷学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/rxl/main.htm" target="_blank" rel="noreferrer">任轩乐学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔中心介绍材料</a>：约 2024 年方向材料。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>：实际开课与要求以教务系统为准。</li></ul>',10))])}const F=c(p,[["render",B]]);export{k as __pageData,F as default};
